using System.Net.WebSockets;
using System.Text.Json;
using Websocket.Client;

namespace VRCX;

#if LINUX
public
#else
internal
#endif
partial class AppApi
{
    private static readonly Uri OvrtWebsocketUri = new("ws://127.0.0.1:11450/api");
    private static readonly byte[] VrcxIcon = Convert.FromBase64String("");
    private static readonly SemaphoreSlim OvrtGate = new(1, 1);
    private static WebsocketClient? OvrtWebsocketClient;

    private static WebsocketClient CreateOvrtClient()
    {
        var dotnetWebsocketClientFactory = new Func<ClientWebSocket>(() =>
        {
            var client = new ClientWebSocket
            {
                Options =
                {
                        KeepAliveInterval = TimeSpan.FromSeconds(5),
                },
            };
            client.Options.SetRequestHeader("user-agent", Program.Version);
            return client;
        });

        var client = new WebsocketClient(OvrtWebsocketUri, dotnetWebsocketClientFactory)
        {
            Name = "OVRToolkit Websocket",

            ReconnectTimeout = null,
            ErrorReconnectTimeout = TimeSpan.FromSeconds(30),
        };

        client.ReconnectionHappened.Subscribe(info =>
        {
            Logger.ConditionalDebug(System.Globalization.CultureInfo.InvariantCulture, "[OVRToolkit Websocket] Reconnection happened, type: {0}", info?.Type.ToString());
        });
        client.DisconnectionHappened.Subscribe(info =>
        {
            Logger.ConditionalDebug(System.Globalization.CultureInfo.InvariantCulture, "[OVRToolkit Websocket] Disconnection happened, type: {0}", info?.Type.ToString());
        });
        client.MessageReceived.Subscribe(msg =>
        {
            Logger.ConditionalDebug(System.Globalization.CultureInfo.InvariantCulture, "[OVRToolkit Websocket] Message received: {0}", msg.Text);
        });

        return client;
    }

    private static async Task<WebsocketClient> GetOvrtClientAsync()
    {
        await OvrtGate.WaitAsync(CancellationToken.None).ConfigureAwait(false);
        try
        {
            if (OvrtWebsocketClient is { } existing)
            {
                return existing;
            }

            OvrtWebsocketClient = CreateOvrtClient();
            await OvrtWebsocketClient.Start().ConfigureAwait(false);
            return OvrtWebsocketClient;
        }
        finally
        {
            _ = OvrtGate.Release();
        }
    }

    private static async Task SendMessagesAsync(List<OvrtMessage> ovrtMessages)
    {
        if (ovrtMessages.Count == 0)
        {
            return;
        }

        WebsocketClient client = await GetOvrtClientAsync().ConfigureAwait(false);
        if (!client.IsRunning)
        {
            return;
        }

        foreach (OvrtMessage message in ovrtMessages)
        {
            _ = client.Send(JsonSerializer.Serialize(message));
        }
    }

    public virtual void OVRTNotification(bool hudNotification, bool wristNotification, string title, string body, int timeout, double opacity, string image = "")
    {
        List<OvrtMessage> messages = [];

        byte[]? imageBytes = null;
        try
        {
            if (!string.IsNullOrWhiteSpace(image) && File.Exists(image))
            {
                imageBytes = File.ReadAllBytes(image);
            }
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or NotSupportedException)
        {
            Logger.Error(ex, System.Globalization.CultureInfo.InvariantCulture, "Failed to read OVRT notification image");
        }
        imageBytes ??= VrcxIcon;

        if (wristNotification)
        {
            messages.Add(new OvrtMessage
            {
                MessageType = "SendWristNotification",
                Json = JsonSerializer.Serialize(new OvrtWristNotificationMessage
                {
                    Body = title + " - " + body,
                }),
            });
        }

        if (hudNotification)
        {
            messages.Add(new OvrtMessage
            {
                MessageType = "SendNotification",
                Json = JsonSerializer.Serialize(new OvrtHudNotificationMessage
                {
                    Title = title,
                    Body = body,
                    Icon = imageBytes,
                }),
            });
        }

        _ = SendMessagesAsync(messages);
    }

    private struct OvrtMessage
    {
        [System.Text.Json.Serialization.JsonPropertyName("messageType")]
        public string MessageType { get; set; }

        [System.Text.Json.Serialization.JsonPropertyName("json")]
        public string Json { get; set; }
    }

    private struct OvrtHudNotificationMessage
    {
        [System.Text.Json.Serialization.JsonPropertyName("title")]
        public string Title { get; set; }

        [System.Text.Json.Serialization.JsonPropertyName("body")]
        public string Body { get; set; }

        [System.Text.Json.Serialization.JsonPropertyName("icon")]
        public byte[] Icon { get; set; }
    }

    private struct OvrtWristNotificationMessage
    {
        [System.Text.Json.Serialization.JsonPropertyName("body")]
        public string Body { get; set; }
    }
}
